"""Select a supported archived dynamics law from paid controls and targets."""
PREDICTORS = [
    'archive/source_000/_evaluated_model/model.py',
    'archive/source_001/_evaluated_model/model.py',
    'archive/source_002/_evaluated_model/model.py',
    'archive/source_003/_evaluated_model/model.py',
    'archive/source_004/_evaluated_model/_evaluated_model/model.py',
    'archive/source_005/_evaluated_model/model.py',
]

def _predict(k, row):
    u = float(row['features']['u'])
    h = row.get('history', [])
    lag2 = float(h[-2]['u']) if len(h) >= 2 else 0.0
    if k == 0:
        return 0.6920194267114789*u - 0.1883668496552205
    if k == 1:
        return 0.692023986971*u - 0.1883668496552205
    if k in (2, 3):
        return -0.05184027526017348 + 1.2207017798364587*u + 1.1179166091930877*lag2
    state = 0.0
    for item in h + [{'u': u}]:
        x = float(item['u'])
        if x >= 0.7:
            state = 1.0
        elif x <= -0.6:
            state = 0.0
    return state

def select_actions(public_spec, observations, memory):
    rows = [row for rec in observations for row in rec.get('rows', [])]
    if not rows:
        return {'actions': [], 'question': 'Classify the response law from paid current and preceding controls.'}
    mse = [sum((float(r['target'])-_predict(k, r))**2 for r in rows)/len(rows) for k in range(6)]
    k = min(range(6), key=lambda j: mse[j])
    # The two confirmed affine coefficients differ slightly; source_001 passed fresh
    # confirmation at MSE <= 1e-10, so use that documented tolerance for selection.
    if mse[k] <= 1e-10:
        return {'model': PREDICTORS[k], 'lesson': 'Paid observations select this previously confirmed archived predictor.'}
    # Otherwise treat the best-fitting archived structure as a revised hypothesis.
    if k in (0, 1):
        code = "def predict(row):\n    return 0.6920194267114789*float(row['features']['u'])-0.1883668496552205\n"
    elif k in (2, 3):
        code = "def predict(row):\n    h=row.get('history', [])\n    lag2=float(h[-2]['u']) if len(h)>=2 else 0.0\n    return -0.05184027526017348+1.2207017798364587*float(row['features']['u'])+1.1179166091930877*lag2\n"
    else:
        code = "def predict(row):\n    state=0.0\n    for item in row.get('history', [])+[{'u':row['features']['u']}]:\n        u=float(item['u'])\n        if u>=0.7: state=1.0\n        elif u<=-0.6: state=0.0\n    return state\n"
    return {'action':'write', 'arguments':{'path':'revised_model.py','code':code}}

"""Select a confirmed prior law when supported; otherwise fit and revise."""
import json
import os

PREDICTORS = [
    'archive/source_000/_evaluated_model/model.py',
    'archive/source_001/_evaluated_model/model.py',
    'archive/source_002/_evaluated_model/model.py',
    'archive/source_003/_evaluated_model/model.py',
    'archive/source_004/_evaluated_model/_evaluated_model/model.py',
    'archive/source_005/_evaluated_model/model.py',
]

def _predict(k, row):
    u = float(row['features']['u'])
    h = row.get('history', [])
    lag2 = float(h[-2]['u']) if len(h) >= 2 else 0.0
    if k == 0:
        return 0.6920194267114789*u - 0.1883668496552205
    if k == 1:
        return 0.692023986971*u - 0.1883668496552205
    if k in (2, 3):
        return -0.05184027526017348 + 1.2207017798364587*u + 1.1179166091930877*lag2
    state = 0.0
    for item in h + [{'u': u}]:
        x = float(item['u'])
        if x >= 0.7:
            state = 1.0
        elif x <= -0.6:
            state = 0.0
    return state

def _rows(records):
    return [r for rec in records for r in rec.get('rows', [])]

def _fit_affine(rows):
    us = [float(r['features']['u']) for r in rows]
    ys = [float(r['target']) for r in rows]
    um, ym = sum(us)/len(us), sum(ys)/len(ys)
    den = sum((u-um)**2 for u in us)
    if den == 0:
        return None
    a = sum((u-um)*(y-ym) for u,y in zip(us,ys))/den
    return a, ym-a*um

def select_actions(public_spec, observations, memory):
    rows = _rows(observations)
    if not rows:
        return {'actions': [], 'question': 'Compare archived dynamics laws against the paid trajectories.'}

    # A previously exported revision is checked against the current complete evidence;
    # do not emit the same write repeatedly during the invocation limit.
    if os.path.exists('revised_model.py'):
        best = min(range(len(PREDICTORS)), key=lambda k: sum((float(r['target'])-_predict(k,r))**2 for r in rows)/len(rows))
        prior_mse = sum((float(r['target'])-_predict(best,r))**2 for r in rows)/len(rows)
        if prior_mse <= 1e-20:
            return {'model': PREDICTORS[best], 'lesson': 'The paid rows exactly support this earlier confirmed predictor.'}
        return {'model': 'revised_model.py', 'lesson': 'The revised law was fitted to paid observations and is ready for confirmation.'}

    errors = [sum((float(r['target'])-_predict(k,r))**2 for r in rows)/len(rows) for k in range(len(PREDICTORS))]
    k = min(range(len(errors)), key=errors.__getitem__)
    # Reuse only when it describes the observations at numerical precision.
    if errors[k] <= 1e-20:
        return {'model': PREDICTORS[k], 'lesson': 'Paid observations select this previously confirmed archived predictor.'}

    fit = _fit_affine(rows)
    if fit is None:
        return {'actions': [], 'question': 'Obtain varied controls to identify the response mapping.'}
    a,b = fit
    code = "def predict(row):\n    return %.17g*float(row['features']['u']) + %.17g\n" % (a,b)
    return {'action':'write', 'arguments':{'path':'revised_model.py','code':code}}

