"""Choose an archived law when paid evidence supports it; otherwise fit candidates."""
import os

PREDICTORS = [
    'archive/source_000/_evaluated_model/model.py',
    'archive/source_001/_evaluated_model/model.py',
    'archive/source_002/_evaluated_model/model.py',
    'archive/source_003/_evaluated_model/model.py',
    'archive/source_004/_evaluated_model/_evaluated_model/model.py',
    'archive/source_005/_evaluated_model/model.py',
]

def _hist(row):
    return [float(x['u']) for x in row.get('history', [])]

def _prior(k, row):
    u = float(row['features']['u'])
    h = _hist(row)
    if k == 0: return 0.6920194267114789*u - 0.1883668496552205
    if k == 1: return 0.692023986971*u - 0.1883668496552205
    if k in (2, 3): return -0.05184027526017348 + 1.2207017798364587*u + 1.1179166091930877*(h[-2] if len(h)>=2 else 0.)
    s = 0.
    for x in h+[u]:
        if x >= .7: s=1.
        elif x <= -.6: s=0.
    return s

def _rows(records):
    return [r for rec in records for r in rec.get('rows', [])]

def _mse(rows, f):
    return sum((float(r['target'])-f(r))**2 for r in rows)/len(rows)

def _linear(rows, lag):
    import numpy as np
    X=[]; y=[]
    for r in rows:
        h=_hist(r); u=float(r['features']['u'])
        X.append([1.,u]+([h[-2] if len(h)>=2 else 0.] if lag else [])); y.append(float(r['target']))
    b=np.linalg.lstsq(np.asarray(X),np.asarray(y),rcond=None)[0]
    return tuple(float(x) for x in b)

def _latch(rows):
    # Search supported discrete control levels for deterministic set/reset thresholds.
    levels=[i/10 for i in range(-10,11)]
    best=(float('inf'),.7,-.6)
    for on in levels:
        for off in levels:
            if off >= on: continue
            def pred(r):
                s=0.
                for x in _hist(r)+[float(r['features']['u'])]:
                    if x>=on: s=1.
                    elif x<=off: s=0.
                return s
            e=_mse(rows,pred)
            if e<best[0]: best=(e,on,off)
    return best[1],best[2]

def select_actions(public_spec, records, memory):
    rows=_rows(records)
    if not rows:
        return {'actions': [], 'question':'Use paid rows to identify which archived dynamics law transfers.'}
    errs=[_mse(rows,lambda r,k=k:_prior(k,r)) for k in range(len(PREDICTORS))]
    k=min(range(len(errs)),key=errs.__getitem__)
    if errs[k] <= 1e-20:
        return {'model':PREDICTORS[k],'lesson':'Paid observations select this previously confirmed archived model.'}
    candidates=[]
    a,b=_linear(rows,False)
    candidates.append(('affine',_mse(rows,lambda r,a=a,b=b:a*float(r['features']['u'])+b),(a,b)))
    a,b,c=_linear(rows,True)
    candidates.append(('lag2',_mse(rows,lambda r,a=a,b=b,c=c:a*float(r['features']['u'])+b+(c*(_hist(r)[-2] if len(_hist(r))>=2 else 0.))),(a,b,c)))
    on,off=_latch(rows)
    def latch(r):
        s=0.
        for x in _hist(r)+[float(r['features']['u'])]:
            if x>=on:s=1.
            elif x<=off:s=0.
        return s
    candidates.append(('latch',_mse(rows,latch),(on,off)))
    name,err,pars=min(candidates,key=lambda x:x[1])
    if name=='affine':
        code="def predict(row):\n    return %.17g*float(row['features']['u']) + %.17g\n"%pars
    elif name=='lag2':
        code="def predict(row):\n    h=row.get('history',[])\n    return %.17g + %.17g*float(row['features']['u']) + %.17g*(float(h[-2]['u']) if len(h)>=2 else 0.0)\n"%pars
    else:
        code="def predict(row):\n    s=0.0\n    for z in row.get('history',[])+[{'u':row['features']['u']}]:\n        x=float(z['u'])\n        if x >= %.17g: s=1.0\n        elif x <= %.17g: s=0.0\n    return s\n"%pars
    if os.path.exists('revised_model.py') and err > 1e-10:
        return {'stop':'Current paid rows do not identify an exact supported candidate.'}
    if err <= 1e-20 and os.path.exists('revised_model.py'):
        return {'model':'revised_model.py','lesson':'A revised candidate fits all paid rows exactly.'}
    return {'action':'write','arguments':{'path':'revised_model.py','code':code}}

"""Choose a confirmed archive law when exact on paid rows; otherwise fit lagged linear or latch laws."""
import os
import numpy as np

PREDICTORS = [
    'archive/source_000/_evaluated_model/model.py',
    'archive/source_001/_evaluated_model/model.py',
    'archive/source_002/_evaluated_model/model.py',
    'archive/source_003/_evaluated_model/model.py',
    'archive/source_004/_evaluated_model/_evaluated_model/model.py',
    'archive/source_005/_evaluated_model/model.py',
]

def _u(row): return float(row['features']['u'])
def _hist(row): return [float(x['u']) for x in row.get('history', [])]
def _rows(records): return [r for rec in records for r in rec.get('rows', [])]
def _mse(rows, f): return float(np.mean([(float(r['target'])-f(r))**2 for r in rows]))

def _prior(k, r):
    u=_u(r); h=_hist(r)
    if k in (0,1): return (0.6920194267114789 if k==0 else 0.692023986971)*u-0.1883668496552205
    if k in (2,3): return -0.05184027526017348+1.2207017798364587*u+1.1179166091930877*(h[-2] if len(h)>=2 else 0.)
    s=0.
    for x in h+[u]:
        if x>=.7:s=1.
n        elif x<=-.6:s=0.
    return s

def select_actions(public_spec, records, memory):
    rows=_rows(records)
    if not rows: return {'actions':[], 'question':'Identify the exact response law from independent trajectories and compare archive candidates.'}
    err=[_mse(rows,lambda r,k=k:_prior(k,r)) for k in range(6)]
    k=min(range(6),key=err.__getitem__)
    if err[k]<1e-20: return {'model':PREDICTORS[k], 'lesson':'Paid observations exactly support this previously confirmed archive predictor.'}
    # Fit y as a linear function of present and recent controls; missing pre-reset controls are zero.
    best=None
    for lag in range(13):
        X=[]; y=[]
        for r in rows:
            h=_hist(r); seq=([0.]*(lag+1-len(h))+h)[-(lag+1):]+[_u(r)]
            X.append([1.]+[seq[-1-j] if len(seq)>j else 0. for j in range(lag+1)])
            y.append(float(r['target']))
        b=np.linalg.lstsq(np.asarray(X),np.asarray(y),rcond=None)[0]
        def pred(r,b=b,lag=lag):
            h=_hist(r); seq=([0.]*(lag+1-len(h))+h)[-(lag+1):]+[_u(r)]
            return float(b[0]+sum(b[j+1]*(seq[-1-j] if len(seq)>j else 0.) for j in range(lag+1)))
        e=_mse(rows,pred)
        if best is None or e<best[0]: best=(e,lag,b)
    # Search thresholds on the public one-decimal control grid.
    latch=(float('inf'),.7,-.6)
    for on in [i/10 for i in range(-10,11)]:
        for off in [i/10 for i in range(-10,11)]:
            if off>=on: continue
            def lp(r,on=on,off=off):
                s=0.
                for x in _hist(r)+[_u(r)]:
                    if x>=on:s=1.
                    elif x<=off:s=0.
                return s
            e=_mse(rows,lp)
            if e<latch[0]:latch=(e,on,off)
    if latch[0]<best[0]:
        e,on,off=latch
        code="def predict(row):\n s=0.0\n for z in row.get('history',[])+[{'u':row['features']['u']}]:\n  x=float(z['u'])\n  if x >= %.17g:s=1.0\n  elif x <= %.17g:s=0.0\n return s\n"%(on,off)
