    if not rows: return {'actions':[], 'question':'Identify the response law from paid trajectories.'}
    errors=[_mse(rows,lambda r,k=k:_prior(k,r)) for k in range(6)]
    k=int(np.argmin(errors))
    if errors[k] < 1e-20:
        return {'model':PREDICTORS[k], 'lesson':'Paid evidence exactly supports this previously confirmed predictor.'}

