"""Reuse exact archived laws; otherwise fit an exact finite-history classifier."""
import os
import numpy as np
from sklearn.tree import DecisionTreeClassifier

PREDICTORS = [
    'archive/source_000/_evaluated_model/model.py',
    'archive/source_001/_evaluated_model/model.py',
    'archive/source_002/_evaluated_model/model.py',
    'archive/source_003/_evaluated_model/model.py',
    'archive/source_004/_evaluated_model/_evaluated_model/model.py',
    'archive/source_005/_evaluated_model/model.py',
]

def _u(r): return float(r['features']['u'])
def _hist(r): return [float(x['u']) for x in r.get('history', [])]
def _rows(records): return [r for rec in records for r in rec.get('rows', [])]
def _mse(rows, f): return float(np.mean([(float(r['target'])-f(r))**2 for r in rows]))
def _prior(k, r):
    u, h = _u(r), _hist(r)
    if k in (0, 1):
        return (0.6920194267114789 if k == 0 else 0.692023986971)*u - 0.1883668496552205
    if k in (2, 3):
        return -0.05184027526017348 + 1.2207017798364587*u + 1.1179166091930877*(h[-2] if len(h) >= 2 else 0.0)
    state = 0.0
    for x in h + [u]:
        if x >= 0.7: state = 1.0
        elif x <= -0.6: state = 0.0
    return state

def select_actions(public_spec, records, memory):
    rows = _rows(records)
    if not rows:
        return {'actions': [], 'question': 'Identify a response law from paid trajectories.'}
    errors = [_mse(rows, lambda r, k=k: _prior(k, r)) for k in range(6)]
    k = int(np.argmin(errors))
    if errors[k] < 1e-20:
        return {'model': PREDICTORS[k], 'lesson': 'Paid evidence exactly supports this previously confirmed archive predictor.'}

    y = np.asarray([float(r['target']) for r in rows])
    best = None
    for width in range(1, min(12, int(public_spec.get('max_probe_length', 24))) + 1):
        X = []
        for r in rows:
            seq = _hist(r) + [_u(r)]
            X.append([seq[-1-j] if len(seq) > j else 0.0 for j in range(width)])
        X = np.asarray(X)
        for depth in range(1, min(20, 2*width + 2) + 1):
            model = DecisionTreeClassifier(max_depth=depth, random_state=0)
            model.fit(X, y)
            if np.array_equal(model.predict(X), y):
                score = (depth, width)
                if best is None or score < best[0]: best = (score, width, model)
                break
    if best is None:
        return {'stop': 'Paid rows do not support an exact compact history classifier.'}
    _, width, model = best
    tree = model.tree_
    left, right = tree.children_left.tolist(), tree.children_right.tolist()
    feat, thresh = tree.feature.tolist(), tree.threshold.tolist()
    vals = tree.value[:, 0, :].tolist()
    code = '''LEFT=%r
RIGHT=%r
FEAT=%r
THRESH=%r
VALUE=%r
def predict(row):
 seq=[float(z["u"]) for z in row.get("history",[])]+[float(row["features"]["u"])]
 x=[seq[-1-j] if len(seq)>j else 0.0 for j in range(%d)]
 n=0
 while LEFT[n] != RIGHT[n]:
  n=LEFT[n] if x[FEAT[n]] <= THRESH[n] else RIGHT[n]
 return float(VALUE[n][0] >= 0.5)
''' % (left, right, feat, thresh, vals, width)
    if os.path.exists('revised_model.py'):
        return {'model': 'revised_model.py', 'lesson': 'Submit the exact fitted history classifier for fresh confirmation.'}
    return {'action': 'write', 'arguments': {'path': 'revised_model.py', 'code': code}}
